// Normalize each Gmail message, carry the Settings along, and flag obvious
// automated or bulk mail so we never spend an AI call (or your attention) on it.
return $input.all().map(item => {
  const m = item.json;
  const headers = m.headers || {};
  // Header values arrive like "list-unsubscribe: <mailto:...>"; compare lowercased.
  const h = key => String(headers[key] || '').toLowerCase();

  const sender = (m.from && m.from.value && m.from.value[0]) || {};
  const fromAddr = String(sender.address || '').toLowerCase();
  const fromName = sender.name || '';
  const subject = m.subject || '';
  // Plain-text body, whitespace collapsed, capped to keep the prompt cheap.
  const body = String(m.text || '').replace(/\s+/g, ' ').trim().slice(0, 6000);

  const automatedSender = /(no-?reply|do-?not-?reply|mailer-daemon|postmaster|notifications?@|newsletter|bounce)/i.test(fromAddr);
  const autoSubmitted = h('auto-submitted');
  const bulkHeaders =
    Boolean(headers['list-unsubscribe']) ||
    /(bulk|list|junk)/.test(h('precedence')) ||
    (autoSubmitted !== '' && !/(^|:\s*)no\s*$/.test(autoSubmitted));
  const isSelf = Boolean(m.myAddress) && fromAddr === String(m.myAddress).toLowerCase();

  // Unlike the auto-reply template, replies (Re:) are NOT skipped here: an ongoing
  // invoice or contract thread is exactly what needs you, and nothing is sent
  // without your approval, so there is no reply loop to guard against.
  let skipReason = '';
  if (isSelf) skipReason = 'sent by me';
  else if (automatedSender) skipReason = 'automated sender (cannot be replied to)';
  else if (bulkHeaders) skipReason = 'bulk or mailing-list headers';

  return {
    json: {
      messageId: m.id,
      threadId: m.threadId,
      fromAddr,
      fromName,
      firstName: fromName.split(/\s+/)[0] || '',
      subject,
      body,
      skipReason,
      approverEmail: m.approverEmail,
      signature: m.signature,
      labelId: m.labelId,
    },
  };
});

