// Turn the form answer into one clear decision.
// If the wait time ran out, the node resumes without form data: decision = "timeout".
const pending = $('Pending Draft').first().json;
const answer = $input.first().json.data;

let decision = 'timeout';
let edited = '';
let notes = '';
if (answer) {
  const choice = String(answer['Decision'] || '').toLowerCase();
  if (choice.startsWith('send')) decision = 'send';
  else if (choice.startsWith('redraft')) decision = 'redraft';
  else decision = 'reject';
  edited = String(answer['Reply to send'] || '').trim();
  notes = String(answer['Notes for redraft'] || '').trim();
}

// An empty reply box means "use the AI draft as is".
const reply = edited || String(pending.draft || '').trim();

return [{
  json: {
    decision,
    reply,
    notes,
    wasEdited: edited !== '' && edited !== String(pending.draft || '').trim(),
    round: pending.round,
    respondedAt: answer ? answer.respondedAt : null,
  },
}];

